package local.remoteandroid.direct;public class BitrateCheck {public static void main(String[] a){if(Bitrate.parseMbps("5.5")!=5500000||Bitrate.parseMbps("0.5")!=500000||Bitrate.parseMbps("12")!=12000000||Bitrate.parseMbps("24")!=24000000||Bitrate.parseMbps("40")!=40000000)throw new AssertionError();for(String s:new String[]{"40.000001","0.499999","","NaN","-1","1.0000001"})try{Bitrate.parseMbps(s);throw new AssertionError(s);}catch(IllegalArgumentException good){}System.out.println("Bitrate input PASS");}}
